declare(strict_types=1);

use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\FixtureFile;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\SourceParser;

require __DIR__ . '/../../../vendor/autoload.php';

[, $major, $archives, $output] = $argv + [null, null, null, __DIR__];
$pins = json_decode(file_get_contents(__DIR__ . '/recipient-sources.json'), true, 512, JSON_THROW_ON_ERROR);
if (!isset($pins[$major]) || !is_dir((string)$archives)) {
    throw new InvalidArgumentException('usage: generate-recipients.php <31..35> <verified archive directory>');
}
$tree = sys_get_temp_dir() . '/mcp-recipient-api-' . bin2hex(random_bytes(6));
mkdir($tree, recursive: true);
try {
    foreach ($pins[$major] as $app => $pin) {
        $file = $archives . '/' . $app . '-' . $pin['version'] . ($app === 'server' ? '.php' : '.tar.gz');
        if (hash_file('sha256', $file) !== $pin['sha256']) {
            throw new RuntimeException('Source SHA256 mismatch: ' . $file);
        }
        if ($app === 'server') {
            mkdir($tree . '/lib/public/AppFramework/Db', recursive: true);
            copy($file, $tree . '/lib/public/AppFramework/Db/QBMapper.php');
            continue;
        }
        $unpack = $tree . '/unpack-' . $app;
        mkdir($unpack);
        (new PharData($file))->extractTo($unpack);
        $directories = glob($unpack . '/*', GLOB_ONLYDIR);
        if (count($directories) !== 1) {
            throw new RuntimeException('Expected one official app root');
        }
        if (!is_dir($tree . '/apps')) {
            mkdir($tree . '/apps');
        }
        rename($directories[0], $tree . '/apps/' . $app);
        $version = (string)simplexml_load_file($tree . '/apps/' . $app . '/appinfo/info.xml')->version;
        if ($version !== ($pin['manifestVersion'] ?? $pin['version'])) {
            throw new RuntimeException('Source app version mismatch: ' . $app);
        }
    }
    $fixture = require __DIR__ . '/' . $major . '.php';
    $parser = new SourceParser($tree);
    foreach (['OCA\\Deck\\Db\\AclMapper', 'OCA\\Deck\\Service\\CirclesService',
        'OCA\\Circles\\Model\\Member', 'OCA\\Circles\\Model\\Circle'] as $class) {
        $surface = $parser->surface($class);
        if ($surface === null) {
            throw new RuntimeException('Official source lacks ' . $class);
        }
        $fixture['classes'][$class] = $surface;
    }
    ksort($fixture['classes']);
    $fixture['recipientSources'] = $pins[$major];
    $original = file_get_contents(__DIR__ . '/' . $major . '.php');
    $header = substr($original, 0, strpos($original, 'return ['));
    $header = preg_replace('~// Recipient surfaces generated[^\n]*\n~', '', $header);
    $header .= "// Recipient surfaces generated by generate-recipients.php; official versions/SHAs below.\n";
    FixtureFile::write($output . '/' . $major . '.php', $header, $fixture);
    echo 'Generated complete recipient surfaces for NC' . $major . "\n";
} finally {
    $files = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($tree,
        FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::CHILD_FIRST);
    foreach ($files as $file) {
        $file->isDir() ? rmdir($file->getPathname()) : unlink($file->getPathname());
    }
    rmdir($tree);
}
